// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am) public {
        vm.assume(am > 0);
        // Call Collect; it may revert or not, but MinSum must remain > 0
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));
        // Regardless of success, MinSum must be > 0
        assertTrue(c.MinSum() > 0);
    }
}

